command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-logical-offset --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "5cdd28c0b7188730a4182f24932d3aaa901b9cae") { throw "main moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-logical-offset origin/work/large-folder-logical-offset
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "a8325cad1eb66db34de33cf104d45819e4cda574") { throw "candidate mismatch" }

python -X utf8 tests\winui\test_large_folder_streaming_contract.py
if ($LASTEXITCODE -ne 0) { throw "streaming source contract failed" }
python -X utf8 tests\winui\test_large_folder_contract.py
if ($LASTEXITCODE -ne 0) { throw "large-folder source contract failed" }
python -X utf8 tests\winui\helper\test_contract.py
if ($LASTEXITCODE -ne 0) { throw "helper source contract failed" }

cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }

$env:FLY_M16_CONFIG = "Release"
python -X utf8 tests\winui\helper\test_process_isolation.py
if ($LASTEXITCODE -ne 0) { throw "focused helper process-isolation test failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_LOGICAL_OFFSET_ACCEPTANCE_PASS"
